    X['aa'] += -0.5 * np.einsum('iyuz,zpyq,vwqixp->vwux', h['aa'][c,a,a,a], lambdas['aa'], t['aaa'][pa,pa,pa,hc,ha,ha], optimize=True)
    X['aa'] += -0.5 * np.einsum('iyuz,zUyV,vwVixU->vwux', h['aa'][c,a,a,a], lambdas['ab'], t['aab'][pa,pa,pA,hc,ha,hA], optimize=True)
    X['aa'] += 0.125 * np.einsum('iyzp,zpyq,uvqiwx->uvwx', h['aa'][c,a,a,a], lambdas['aa'], t['aaa'][pa,pa,pa,hc,ha,ha], optimize=True)
    X['aa'] += -0.5 * np.einsum('iIuA,vwAixI->vwux', h['ab'][c,C,a,V], t['aab'][pa,pa,pV,hc,ha,hC], optimize=True)
    X['aa'] += -0.5 * np.einsum('iUuV,yVzU,vwzixy->vwux', h['ab'][c,A,a,A], lambdas['ab'], t['aaa'][pa,pa,pa,hc,ha,ha], optimize=True)
