    X['a'] += -0.5 * np.einsum('IJAB,wUxV,xVwJ,uABvIU->uv', h['bb'][C,C,V,V], lambdas['ab'], t['ab'][pa,pA,ha,hC], t['abb'][pa,pV,pV,ha,hC,hA], optimize=True)
