    X['a'] += -0.5 * np.einsum('IJAB,wUxV,xAwU,uVBvIJ->uv', h['bb'][C,C,V,V], lambdas['ab'], t['ab'][pa,pV,ha,hA], t['abb'][pa,pA,pV,ha,hC,hC], optimize=True)
    X['a'] += 0.25 * np.einsum('IJAB,UVWX,uXvJ,WABIUV->uv', h['bb'][C,C,V,V], lambdas['bb'], t['ab'][pa,pA,ha,hC], t['bbb'][pA,pV,pV,hC,hA,hA], optimize=True)
    X['a'] += -0.25 * np.einsum('IJAB,UVWX,uBvU,WXAIJV->uv', h['bb'][C,C,V,V], lambdas['bb'], t['ab'][pa,pV,ha,hA], t['bbb'][pA,pA,pV,hC,hC,hA], optimize=True)
