def Hbar_ncomm2_nbody2(X, h, t, gamma1, eta1, lambdas, orbspace, verbose=False):
    tic = time.time()
    c = orbspace['core_alpha']
    C = orbspace['core_beta']
    a = orbspace['active_alpha']
    A = orbspace['active_beta']
    v = orbspace['virt_alpha']
    V = orbspace['virt_beta']
    hc = orbspace['hole_core_alpha']
    hC = orbspace['hole_core_beta']
    ha = orbspace['hole_active_alpha']
    hA = orbspace['hole_active_beta']
    pa = orbspace['particle_active_alpha']
    pA = orbspace['particle_active_beta']
    pv = orbspace['particle_virt_alpha']
    pV = orbspace['particle_virt_beta']

    # AA|AA
    X['bb'] += -1.0 * np.einsum('uv,ijua,aUiV,vWjX->UWVX', eta1['a'], h['aa'][c,c,a,v], t['ab'][pv,pA,hc,hA], t['ab'][pa,pA,hc,hA], optimize=True)
    X['bb'] += -0.5 * np.einsum('uv,iIuU,vi,VWIX->VWUX', eta1['a'], h['ab'][c,C,a,A], t['a'][pa,hc], t['bb'][pA,pA,hC,hA], optimize=True)
    X['bb'] += -1.0 * np.einsum('uv,iIuU,VI,vWiX->VWUX', eta1['a'], h['ab'][c,C,a,A], t['b'][pA,hC], t['ab'][pa,pA,hc,hA], optimize=True)
    X['bb'] += 0.5 * np.einsum('uv,iIuA,UVIW,vAiX->UVWX', eta1['a'], h['ab'][c,C,a,V], t['bb'][pA,pA,hC,hA], t['ab'][pa,pV,hc,hA], optimize=True)
    X['bb'] += -1.0 * np.einsum('uv,iIuA,UAIV,vWiX->UWVX', eta1['a'], h['ab'][c,C,a,V], t['bb'][pA,pV,hC,hA], t['ab'][pa,pA,hc,hA], optimize=True)
    X['bb'] += -0.5 * np.einsum('uv,iIuA,UAVW,vXiI->UXVW', eta1['a'], h['ab'][c,C,a,V], t['bb'][pA,pV,hA,hA], t['ab'][pa,pA,hc,hC], optimize=True)
    X['bb'] += -0.5 * np.einsum('uv,iIaU,aVuI,vWiX->VWUX', eta1['a'], h['ab'][c,C,v,A], t['ab'][pv,pA,ha,hC], t['ab'][pa,pA,hc,hA], optimize=True)
    X['bb'] += 0.5 * np.einsum('uv,iIaU,aVuW,vXiI->VXUW', eta1['a'], h['ab'][c,C,v,A], t['ab'][pv,pA,ha,hA], t['ab'][pa,pA,hc,hC], optimize=True)
    X['bb'] += -0.5 * np.einsum('uv,iUuA,vi,VAWX->UVWX', eta1['a'], h['ab'][c,A,a,V], t['a'][pa,hc], t['bb'][pA,pV,hA,hA], optimize=True)
    X['bb'] += 1.0 * np.einsum('uv,iUuA,AV,vWiX->UWVX', eta1['a'], h['ab'][c,A,a,V], t['b'][pV,hA], t['ab'][pa,pA,hc,hA], optimize=True)
    X['bb'] += 0.5 * np.einsum('uv,iUaV,vi,aWuX->UWVX', eta1['a'], h['ab'][c,A,v,A], t['a'][pa,hc], t['ab'][pv,pA,ha,hA], optimize=True)
    X['bb'] += 0.5 * np.einsum('uv,iUaV,au,vWiX->UWVX', eta1['a'], h['ab'][c,A,v,A], t['a'][pv,ha], t['ab'][pa,pA,hc,hA], optimize=True)
    X['bb'] += -0.5 * np.einsum('uv,iUaA,aVuW,vAiX->UVWX', eta1['a'], h['ab'][c,A,v,V], t['ab'][pv,pA,ha,hA], t['ab'][pa,pV,hc,hA], optimize=True)
    X['bb'] += 0.5 * np.einsum('uv,iUaA,aAuV,vWiX->UWVX', eta1['a'], h['ab'][c,A,v,V], t['ab'][pv,pV,ha,hA], t['ab'][pa,pA,hc,hA], optimize=True)
    X['bb'] += -0.25 * np.einsum('YZ,iIaU,VWIY,aZiX->VWUX', eta1['b'], h['ab'][c,C,v,A], t['bb'][pA,pA,hC,hA], t['ab'][pv,pA,hc,hA], optimize=True)
