    X['bb'] += 0.5 * np.einsum('YZ,IJUA,VAIY,WZJX->VWUX', eta1['b'], h['bb'][C,C,A,V], t['bb'][pA,pV,hC,hA], t['bb'][pA,pA,hC,hA], optimize=True)
