    X['bb'] += -1.0 * np.einsum('YZ,IJYA,UAIV,WZJX->UWVX', eta1['b'], h['bb'][C,C,A,V], t['bb'][pA,pV,hC,hA], t['bb'][pA,pA,hC,hA], optimize=True)
    X['bb'] += 0.25 * np.einsum('YZ,IJYA,UAVW,XZIJ->UXVW', eta1['b'], h['bb'][C,C,A,V], t['bb'][pA,pV,hA,hA], t['bb'][pA,pA,hC,hC], optimize=True)
    X['bb'] += -0.5 * np.einsum('YZ,IJYA,ZAIU,VWJX->VWUX', eta1['b'], h['bb'][C,C,A,V], t['bb'][pA,pV,hC,hA], t['bb'][pA,pA,hC,hA], optimize=True)
    X['bb'] += 0.125 * np.einsum('YZ,IJYA,ZAUV,WXIJ->WXUV', eta1['b'], h['bb'][C,C,A,V], t['bb'][pA,pV,hA,hA], t['bb'][pA,pA,hC,hC], optimize=True)
    X['bb'] += -0.5 * np.einsum('YZ,IUVA,ZI,WAXY->UWVX', eta1['b'], h['bb'][C,A,A,V], t['b'][pA,hC], t['bb'][pA,pV,hA,hA], optimize=True)
    X['bb'] += 0.5 * np.einsum('YZ,IUVA,AY,WZIX->UWVX', eta1['b'], h['bb'][C,A,A,V], t['b'][pV,hA], t['bb'][pA,pA,hC,hA], optimize=True)
    X['bb'] += 0.5 * np.einsum('YZ,IUYA,VI,ZAWX->UVWX', eta1['b'], h['bb'][C,A,A,V], t['b'][pA,hC], t['bb'][pA,pV,hA,hA], optimize=True)
    X['bb'] += -0.5 * np.einsum('YZ,IUYA,ZI,VAWX->UVWX', eta1['b'], h['bb'][C,A,A,V], t['b'][pA,hC], t['bb'][pA,pV,hA,hA], optimize=True)
    X['bb'] += -1.0 * np.einsum('YZ,IUYA,AV,WZIX->UWVX', eta1['b'], h['bb'][C,A,A,V], t['b'][pV,hA], t['bb'][pA,pA,hC,hA], optimize=True)
    X['bb'] += -0.5 * np.einsum('YZ,IUAB,VAWY,ZBIX->UVWX', eta1['b'], h['bb'][C,A,V,V], t['bb'][pA,pV,hA,hA], t['bb'][pA,pV,hC,hA], optimize=True)
    X['bb'] += 0.25 * np.einsum('YZ,IUAB,ZBVW,XAIY->UXVW', eta1['b'], h['bb'][C,A,V,V], t['bb'][pA,pV,hA,hA], t['bb'][pA,pV,hC,hA], optimize=True)
