    X['bb'] += 0.125 * np.einsum('YZ,UVAB,AY,ZBWX->UVWX', eta1['b'], h['bb'][A,A,V,V], t['b'][pV,hA], t['bb'][pA,pV,hA,hA], optimize=True)
    X['bb'] += -1.0 * np.einsum('uv,ivab,aUuV,bWiX->UWVX', gamma1['a'], h['aa'][c,a,v,v], t['ab'][pv,pA,ha,hA], t['ab'][pv,pA,hc,hA], optimize=True)
    X['bb'] += 0.5 * np.einsum('uv,iIaU,aVuI,vWiX->VWUX', gamma1['a'], h['ab'][c,C,v,A], t['ab'][pv,pA,ha,hC], t['ab'][pa,pA,hc,hA], optimize=True)
    X['bb'] += -0.5 * np.einsum('uv,iIaU,aVuW,vXiI->VXUW', gamma1['a'], h['ab'][c,C,v,A], t['ab'][pv,pA,ha,hA], t['ab'][pa,pA,hc,hC], optimize=True)
    X['bb'] += -0.5 * np.einsum('uv,iUaV,vi,aWuX->UWVX', gamma1['a'], h['ab'][c,A,v,A], t['a'][pa,hc], t['ab'][pv,pA,ha,hA], optimize=True)
